/bin/zsh -lc "cat > tb.sv <<'EOF'
module tb;
  reg clk=0, rst_n=0, data=0, data_valid=0;
  wire match;
  TopModule dut(.clk(clk), .rst_n(rst_n), .data(data), .data_valid(data_valid), .match(match));
  always #5 clk = ~clk;

  task send(input bit v, input bit d);
    begin
      @(negedge clk);
      data_valid = v;
      data = d;
      @(posedge clk);
      "'$display("t=%0t v=%0b d=%0b match=%0b pstate=%0d nstate=%0d", $time, data_valid, data, match, dut.pstate, dut.nstate);
    end
  endtask

  initial begin
    repeat (2) @(posedge clk);
    rst_n = 1;
    send(1,0);
    send(1,1);
    send(1,1);
    send(1,0);
    send(0,1);
    send(1,0);
    send(1,1);
    send(1,1);
    send(1,0);
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

